#include "facts/generated/facts_data.hpp"

namespace nikos::facts::data {

const Fact kSpaceFacts[kFactsPerCategory] = {
    {u8"space-001", u8"Obrót dłuższy od roku", u8"Wenus obraca się wokół osi przez 243 dni ziemskie, a Słońce obiega w 225 dni. Jednak od wschodu do wschodu Słońca mija tam około 117 dni."},
    {u8"space-002", u8"Oddalający się Księżyc", u8"Księżyc oddala się od Ziemi średnio o 3,8 cm rocznie. To mniej więcej tyle, ile rosną paznokcie w ciągu roku."},
    {u8"space-003", u8"Saturn lżejszy od wody", u8"Średnia gęstość Saturna jest mniejsza od gęstości wody. Gdyby istniał odpowiednio wielki zbiornik, planeta mogłaby w teorii unosić się na wodzie."},
    {u8"space-004", u8"Niebieski zachód na Marsie", u8"Na Marsie niebo wokół zachodzącego Słońca bywa niebieskawe. To efekt rozpraszania światła przez drobny pył."},
    {u8"space-005", u8"Neptun odkryty obliczeniami", u8"Położenie Neptuna obliczono, zanim odnaleziono go na niebie. Wskazówką były niewyjaśnione zaburzenia ruchu Urana."},
    {u8"space-006", u8"Spóźnione światło Słońca", u8"Obraz Słońca dociera do nas z opóźnieniem. Jego światło potrzebuje około 8 minut i 20 sekund, by dotrzeć do Ziemi."},
    {u8"space-007", u8"Gejzery Enceladusa", u8"Z Enceladusa, księżyca Saturna, tryskają w kosmos lód i para. Pod jego lodową skorupą ukryty jest ocean."},
    {u8"space-008", u8"Kosmiczne latarnie", u8"Pulsary wysyłają regularne błyski niczym latarnie morskie. To wirujące gwiazdy neutronowe, których wiązki promieniowania omiatają kosmos."},
    {u8"space-009", u8"Ukryte planety", u8"Planetę można odkryć, nawet jeśli jej nie widać. Przechodząc przed gwiazdą, na chwilę przyciemnia jej światło."},
    {u8"space-010", u8"Podróż Voyagera 1", u8"Voyager 1 dotarł do przestrzeni międzygwiazdowej w 2012 roku. Minięcie zewnętrznych granic obłoku Oorta może mu zająć jeszcze około 30 tysięcy lat."},
    {u8"space-011", u8"Lód na Merkurym", u8"Na Merkurym, najbliższej Słońcu planecie, odkryto lód wodny. Przetrwał w kraterach, do których nigdy nie dociera światło Słońca."},
    {u8"space-012", u8"Długa zima Urana", u8"Na Uranie zima przy biegunie może trwać około 21 ziemskich lat. Planeta obraca się niemal na boku."},
    {u8"space-013", u8"Wirujący Jowisz", u8"Jowisz jest największą planetą i obraca się najszybciej. Pełny obrót zajmuje mu niecałe 10 godzin."},
    {u8"space-014", u8"Wulkan na Io", u8"Na Io, księżycu Jowisza, sfotografowano wybuch wulkanu. Pióropusz gazu i pyłu sięgał 400 km nad powierzchnię."},
    {u8"space-015", u8"Ganimedes większy od Merkurego", u8"Ganimedes, księżyc Jowisza, jest większy od Merkurego. To jedyny znany księżyc z własnym polem magnetycznym."},
    {u8"space-016", u8"Ocean pod lodem Europy", u8"Europa, księżyc Jowisza, prawdopodobnie skrywa ocean. Może mieć dwa razy więcej wody niż wszystkie ziemskie oceany."},
    {u8"space-017", u8"Metanowy deszcz na Tytanie", u8"Na Tytanie, księżycu Saturna, pada metanowy deszcz. Tamtejsze jeziora wypełniają ciekły metan i etan."},
    {u8"space-018", u8"Lodowe góry Plutona", u8"Na Plutonie wznoszą się góry z lodu wodnego. W tamtejszym mrozie taki lód jest twardy jak skała."},
    {u8"space-019", u8"Masa Słońca", u8"Słońce skupia około 99,8% masy całego Układu Słonecznego. Na wszystkie planety i pozostałe ciała przypada zaledwie 0,2%."},
    {u8"space-020", u8"16 wschodów na ISS", u8"Z pokładu ISS można zobaczyć 16 wschodów Słońca na dobę. Stacja okrąża Ziemię co około 90 minut."},
    {u8"space-021", u8"Dwa warkocze komety", u8"Warkocz jonowy komety jest odpychany od Słońca przez wiatr słoneczny. Warkocz pyłowy reaguje głównie na ciśnienie światła i może się zakrzywiać."},
    {u8"space-022", u8"Słońce i Księżyc na niebie", u8"Słońce jest około 400 razy szersze od Księżyca i średnio około 400 razy dalej. Dlatego ich tarcze mają zbliżone rozmiary kątowe."},
    {u8"space-023", u8"Czarna dziura jak soczewka", u8"Czarna dziura potrafi zniekształcić obraz odległej gwiazdy. Jej grawitacja ugina światło niczym ogromna soczewka."},
    {u8"space-024", u8"Tlen z Marsa", u8"Na Marsie urządzenie MOXIE wytworzyło tlen z atmosfery. Rozdzielało dwutlenek węgla na tlen i tlenek węgla."},
    {u8"space-025", u8"Łączność za Księżycem", u8"Z dalekiej strony Księżyca nie ma bezpośredniej łączności z Ziemią. Sygnał zasłania sam Księżyc, więc potrzebny jest przekaźnik."},
    {u8"space-026", u8"Kolory gwiazd", u8"Niebieskie gwiazdy są gorętsze od czerwonych. Pierwsze mogą mieć ponad 30 000 K, drugie około 3000 K."},
    {u8"space-027", u8"Biały karzeł", u8"Biały karzeł może mieć rozmiary Ziemi. W tak małym obiekcie mieści się nawet połowa masy Słońca."},
    {u8"space-028", u8"Gorąca korona Słońca", u8"Zewnętrzna atmosfera Słońca jest gorętsza od jego powierzchni. Osiąga miliony stopni, choć powierzchnia ma około 5500°C."},
    {u8"space-029", u8"Gwiazdy żyjące biliony lat", u8"Niektóre gwiazdy mogą żyć dłużej, niż istnieje Wszechświat. Małym czerwonym karłom paliwo może wystarczyć na biliony lat."},
    {u8"space-030", u8"Złoto z gwiazd neutronowych", u8"Złoto może powstawać przy zderzeniu gwiazd neutronowych. W takim kataklizmie tworzą się też platyna i inne ciężkie pierwiastki."},
    {u8"space-031", u8"Andromeda gołym okiem", u8"Przy ciemnym niebie galaktykę Andromedy widać bez teleskopu. Jej światło dociera do nas po około 2,5 miliona lat."},
    {u8"space-032", u8"Najstarsze światło", u8"Istnieje światło starsze niż wszystkie gwiazdy. Wyemitowano je około 380 000 lat po Wielkim Wybuchu."},
    {u8"space-033", u8"Niewidzialne 95% Wszechświata", u8"Zwykła materia to tylko około 5% zawartości Wszechświata. Reszta przypada na ciemną materię i ciemną energię."},
    {u8"space-034", u8"Tysiące galaktyk Hubble’a", u8"Na jednym obrazie Hubble'a widać około 5500 galaktyk. To maleńki fragment nieba, mniejszy niż tarcza Księżyca."},
    {u8"space-035", u8"Samotne planety", u8"Nie wszystkie planety krążą wokół gwiazd. Część samotnych planet mogła zostać wyrzucona z dawnych układów."},
    {u8"space-036", u8"Cisza w kosmosie", u8"W kosmicznej próżni nie słychać nawet wybuchu. Dźwięk potrzebuje materii, by się rozchodzić."},
    {u8"space-037", u8"Zegary GPS i Einstein", u8"Zegary satelitów GPS wyprzedzają ziemskie o 38 mikrosekund na dobę. Nawigacja musi uwzględniać teorię względności Einsteina."},
    {u8"space-038", u8"Fale grawitacyjne", u8"W 2015 roku po raz pierwszy wykryto fale grawitacyjne. Powstały podczas zderzenia dwóch czarnych dziur."},
    {u8"space-039", u8"Mars pozornie zawraca", u8"Mars potrafi na nocnym niebie pozornie zawrócić. To złudzenie, gdy szybsza Ziemia wyprzedza go na orbicie."},
    {u8"space-040", u8"Spadające gwiazdy", u8"Spadająca gwiazda może być wielkości ziarnka piasku. To drobina, której przelot rozświetla atmosferę."},
    {u8"space-041", u8"Hel odkryty na Słońcu", u8"Hel odkryto na Słońcu, zanim znaleziono go na Ziemi. Zdradziła go nieznana żółta linia w widmie światła."},
    {u8"space-042", u8"Pierwszy obraz czarnej dziury", u8"Pierwszy obraz cienia czarnej dziury pokazano w 2019 roku. Jasny pierścień tworzy gorący gaz wokół niej."},
    {u8"space-043", u8"Czerwone światło galaktyk", u8"Światło odległych galaktyk jest rozciągnięte ku czerwieni. To ślad rozszerzania się samej przestrzeni."},
    {u8"space-044", u8"Gwiazda Polarna", u8"Gwiazda Polarna nie jest najjaśniejszą gwiazdą nieba. Pokazuje północ, bo leży blisko kierunku ziemskiej osi obrotu."},
    {u8"space-045", u8"Radioteleskopy", u8"Radioteleskopy mogą badać kosmos nawet za dnia. Dłuższe fale radiowe przechodzą także przez chmury."},
    {u8"space-046", u8"Lustro teleskopu Webba", u8"Lustro teleskopu Webba ma 18 sześciokątnych części. Złożono je do startu, bo całe lustro nie mieściło się w rakiecie."},
    {u8"space-047", u8"Sonda Parker", u8"Sonda Parker przeleciała przez zewnętrzną atmosferę Słońca. Przed żarem chroni ją specjalna osłona."},
    {u8"space-048", u8"Dlaczego astronauci się unoszą", u8"Astronauci na stacji kosmicznej unoszą się mimo grawitacji. Stacja i wszystko w niej nieustannie spadają wokół Ziemi."},
    {u8"space-049", u8"Zdjęcia z powierzchni Wenus", u8"Wenera 13 pracowała na powierzchni Wenus tylko 127 minut. Zdążyła przesłać pierwsze kolorowe zdjęcia jej krajobrazu."},
    {u8"space-050", u8"Próbki asteroidy Bennu", u8"Sonda OSIRIS-REx przywiozła na Ziemię próbki asteroidy Bennu. W ich minerałach znaleziono ślady dawnego kontaktu z wodą."},
    {u8"space-051", u8"Planety wokół pulsarów", u8"Pierwsze potwierdzone egzoplanety odkryto przy pulsarze. Krążą wokół pozostałości po martwej gwieździe."},
    {u8"space-052", u8"Gorące jowisze", u8"Niektóre gazowe olbrzymy okrążają swoje gwiazdy w kilka dni. Nazywa się je gorącymi jowiszami."},
    {u8"space-053", u8"Planety z dwoma słońcami", u8"Istnieją planety okrążające dwie gwiazdy naraz. Ich niebo może mieć dwa słońca."},
    {u8"space-054", u8"Blokada pływowa", u8"Księżyc stale pokazuje Ziemi niemal tę samą półkulę. To skutek synchronizacji obrotu z obiegiem."},
    {u8"space-055", u8"Odwrotna rotacja Wenus", u8"Wenus obraca się w kierunku przeciwnym do większości planet. Dlatego Słońce pozornie wschodzi tam na zachodzie."},
    {u8"space-056", u8"Sześciokąt na Saturnie", u8"Nad północnym biegunem Saturna wiruje strumień gazu w kształcie sześciokąta. Jego średnica przekracza dwukrotność średnicy Ziemi."},
    {u8"space-057", u8"Pierścienie nie tylko Saturna", u8"Pierścienie mają również Jowisz, Uran i Neptun. Są jednak znacznie słabiej widoczne niż pierścienie Saturna."},
    {u8"space-058", u8"Krótki rok Merkurego", u8"Merkury obiega Słońce w około 88 ziemskich dni. To najkrótszy rok w Układzie Słonecznym."},
    {u8"space-059", u8"Deszcz diamentów?", u8"W głębi Urana i Neptuna mogą powstawać kryształy diamentu. To hipoteza oparta na modelach i eksperymentach."},
    {u8"space-060", u8"Księżyc z oceanem magmy", u8"Młody Księżyc prawdopodobnie miał ocean stopionych skał. Świadczy o tym skład jego dawnej skorupy."},
    {u8"space-061", u8"Żagiel napędzany światłem", u8"Światło Słońca wywiera niewielki nacisk na powierzchnie. Żagiel kosmiczny może dzięki niemu zmieniać ruch sondy bez zużywania paliwa."},
    {u8"space-062", u8"Pomiędzy planetą a gwiazdą", u8"Brązowe karły są zbyt mało masywne, by trwale podtrzymywać syntezę wodoru jak gwiazdy. Nie są jednak zwykłymi planetami."},
    {u8"space-063", u8"Gwiazdy podwójne", u8"Wiele gwiazd należy do układów wielokrotnych. Dwie gwiazdy mogą krążyć wokół wspólnego środka masy."},
    {u8"space-064", u8"Niebo w podczerwieni", u8"Pył kosmiczny przesłania część światła widzialnego. Obserwacje w podczerwieni pozwalają zajrzeć do obłoków pyłu."},
    {u8"space-065", u8"Gwiazdy i pierwiastki", u8"W gwiazdach powstają liczne pierwiastki cięższe od helu. Część trafia do przestrzeni po śmierci gwiazd."},
    {u8"space-066", u8"Mgławica planetarna", u8"Mgławica planetarna nie musi mieć nic wspólnego z planetami. Tworzy ją materia odrzucona przez starzejącą się gwiazdę."},
    {u8"space-067", u8"Słońce nie jest w centrum", u8"Słońce krąży wokół centrum Drogi Mlecznej. Pełen obieg trwa około 230 milionów lat."},
    {u8"space-068", u8"Spłaszczone gwiazdy", u8"Bardzo szybki obrót może spłaszczać gwiazdę na biegunach. Wtedy jej równik jest wyraźnie szerszy."},
    {u8"space-069", u8"Gromady kuliste", u8"Gromady kuliste skupiają nawet setki tysięcy starych gwiazd. Krążą wokół wielu galaktyk."},
    {u8"space-070", u8"Planeta na skraju", u8"Neptun został odwiedzony z bliska tylko przez jedną sondę. Był nią Voyager 2 w 1989 roku."},
    {u8"space-071", u8"Ciemne niebo Księżyca", u8"Na Księżycu nie ma gęstej atmosfery rozpraszającej błękitne światło. Niebo wygląda czarno nawet za dnia."},
    {u8"space-072", u8"Szybkie rozbłyski radiowe", u8"Szybkie błyski radiowe trwają ułamki sekund. Część z nich powiązano z magnetarami."},
    {u8"space-073", u8"Największa góra Marsa", u8"Olympus Mons to olbrzymi wulkan tarczowy na Marsie. Jego wysokość wynosi około 22 km, zależnie od poziomu odniesienia."},
    {u8"space-074", u8"Planeta zdradza swoją masę", u8"Niewidoczną planetę można wykryć po drobnych zmianach prędkości jej gwiazdy. Gwiazda i planeta krążą wokół wspólnego środka masy."},
    {u8"space-075", u8"Neutrina w antarktycznym lodzie", u8"Detektor IceCube wykrywa ślady neutrin w lodzie Antarktydy. Niektóre z tych cząstek przybywają spoza Układu Słonecznego."},
    {u8"space-076", u8"Pustka nie jest pusta", u8"Nawet próżnia kosmiczna zawiera cząstki i promieniowanie. Przestrzeń między galaktykami nie jest idealnie pusta."},
    {u8"space-077", u8"Dlaczego planety są kuliste", u8"Grawitacja dużych ciał przyciąga materię ku środkowi. Dlatego duże planety przyjmują kształt bliski kuli."},
    {u8"space-078", u8"Skąd bierze się zaćmienie", u8"Zaćmienie Słońca zachodzi, gdy Księżyc zasłania jego tarczę. Nie zdarza się przy każdym nowiu z powodu nachylenia orbity."},
    {u8"space-079", u8"Wodór we Wszechświecie", u8"Wodór jest najpowszechniejszym pierwiastkiem we Wszechświecie. Powstał w ogromnej ilości krótko po Wielkim Wybuchu."},
    {u8"space-080", u8"Dwie różne strony Księżyca", u8"Skorupa po niewidocznej z Ziemi stronie Księżyca jest średnio grubsza. Pomogła to wykazać misja GRAIL."},
    {u8"space-081", u8"Księżyc się trzęsie", u8"Na Księżycu występują trzęsienia zwane moonquakes. Niektóre są związane z pływami wywoływanymi przez Ziemię."},
    {u8"space-082", u8"Dzień na Plutonie", u8"Pluton obraca się wokół osi przez około 6,4 ziemskiego dnia. Jego największy księżyc Charon ma podobny okres obiegu."},
    {u8"space-083", u8"Ogrody na orbicie", u8"Na ISS uprawiano między innymi sałatę i rzodkiewki. Badania roślin pomagają planować długie loty kosmiczne."},
    {u8"space-084", u8"Najjaśniejsza planeta", u8"Wenus zwykle świeci na naszym niebie jaśniej niż inne planety. Pomagają w tym jej chmury odbijające światło Słońca."},
    {u8"space-085", u8"Mars ma dwa księżyce", u8"Marsowi towarzyszą Fobos i Deimos. Oba są małe i mają nieregularne kształty."},
    {u8"space-086", u8"Słońce też wiruje", u8"Słońce nie obraca się jak sztywna kula. Jego równik wiruje szybciej niż okolice biegunów."},
    {u8"space-087", u8"Ciemne plamy Słońca", u8"Plamy słoneczne są chłodniejsze od otoczenia. Wciąż jednak są bardzo gorące i wiążą się z silnymi polami magnetycznymi."},
    {u8"space-088", u8"Japet — księżyc o dwóch barwach", u8"Japet, księżyc Saturna, ma jedną półkulę bardzo ciemną, a drugą znacznie jaśniejszą. Różnicę potwierdziły obserwacje sond."},
    {u8"space-089", u8"Kosmiczna sieć", u8"Galaktyki tworzą ogromne włókna i gromady. Pomiędzy nimi znajdują się rozległe obszary o małej gęstości materii."},
    {u8"space-090", u8"Droga Mleczna ma halo", u8"Naszą galaktykę otacza rozległe halo gwiazd i ciemnej materii. Wykracza ono daleko poza jasny dysk galaktyczny."},
    {u8"space-091", u8"Triton krąży pod prąd", u8"Triton, największy księżyc Neptuna, krąży przeciwnie do obrotu planety. To wskazówka, że mógł zostać przechwycony przez jej grawitację."},
    {u8"space-092", u8"Granica Układu Słonecznego", u8"Wpływ wiatru słonecznego tworzy wokół Słońca ogromny obszar zwany heliosferą. Jej rozmiary zmieniają się pod wpływem otoczenia."},
    {u8"space-093", u8"Gwiazdy o dwóch twarzach", u8"Układ zaćmieniowy to dwie gwiazdy zasłaniające się wzajemnie. Ich zmiany jasności zdradzają rozmiary i orbity."},
    {u8"space-094", u8"Chemia między gwiazdami", u8"W przestrzeni międzygwiazdowej wykryto liczne cząsteczki. Wśród nich są związki organiczne obecne w zimnych obłokach."},
    {u8"space-095", u8"Merkury z ogonem", u8"Merkury ma rozległy, bardzo słaby ogon sodowy przypominający kometarny. Tworzą go atomy uwalniane z powierzchni planety."},
    {u8"space-096", u8"Gwiazdy wyrzucone z domu", u8"Niektóre gwiazdy pędzą przez kosmos po wyrzuceniu z macierzystej gromady. Mogą je rozpędzać grawitacyjne spotkania innych gwiazd."},
    {u8"space-097", u8"Dlaczego Mars jest czerwony", u8"Czerwony odcień Marsa pochodzi głównie od związków żelaza. Pył pokrywający planetę zawiera utlenione minerały."},
    {u8"space-098", u8"Zorze na innych planetach", u8"Zorze obserwuje się nie tylko na Ziemi. Występują też między innymi na Jowiszu i Saturnie."},
    {u8"space-099", u8"Prędkość ucieczki z Ziemi", u8"Przy powierzchni Ziemi prędkość ucieczki wynosi około 11,2 km/s. Dotyczy to idealnego ruchu bez dalszego napędu i oporu powietrza."},
    {u8"space-100", u8"Podróż gwiazd", u8"Gwiazdy zmieniają położenie na niebie także względem siebie. Ten powolny ruch własny mierzą obserwatoria takie jak Gaia."},
};

}  // namespace nikos::facts::data
